//! Lookup and command-building examples missing from the executor census.
//! Observations are generated by capture_source_examples.rb on ukiryu ab6df353.
#![cfg(unix)]

use serde_json::Value;
use std::os::unix::fs::PermissionsExt;
use ukiryu::environment::Environment;
use ukiryu::executable::{find_in_path, DiscoveryContext, Platform};
use ukiryu::execution::Seconds;
use ukiryu::executor::{execute, ExecuteRequest};
use ukiryu::runtime::ShellName;

fn golden() -> Value {
    serde_json::from_str(include_str!("executor_data/source_examples.json")).unwrap()
}

#[test]
fn command_building_matches_executor_examples() {
    for row in golden()["commands"].as_array().unwrap() {
        let request = ExecuteRequest::new(
            row["executable"].as_str().unwrap(),
            row["arguments"]
                .as_array()
                .unwrap()
                .iter()
                .map(|a| a.as_str().unwrap().to_owned())
                .collect(),
            Environment::new(),
            ShellName::Bash,
            Seconds::Int(30),
        );
        assert_eq!(request.command_line(), row["command"], "{row}");
        let execution = execute(request).unwrap();
        let hex = |bytes: &[u8]| bytes.iter().map(|b| format!("{b:02x}")).collect::<String>();
        assert_eq!(hex(execution.result.stdout()), row["stdout_hex"], "{row}");
        assert_eq!(hex(execution.result.stderr()), row["stderr_hex"], "{row}");
        assert_eq!(execution.result.exit_status(), row["exit_status"], "{row}");
    }
}

#[test]
fn lookup_path_and_additional_paths_match_executor_examples() {
    let dir = std::env::temp_dir().join(format!("ukiryu-executor-lookup-{}", std::process::id()));
    // Only create a fresh directory owned by this invocation.
    std::fs::create_dir(&dir).expect("fresh lookup fixture");
    struct Cleanup(std::path::PathBuf);
    impl Drop for Cleanup {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }
    let _cleanup = Cleanup(dir.clone());
    let first = dir.join("path");
    let extra = dir.join("extra");
    std::fs::create_dir(&first).unwrap();
    std::fs::create_dir(&extra).unwrap();
    for (parent, name) in [
        (&first, "common"),
        (&extra, "common"),
        (&extra, "extra_only"),
    ] {
        let path = parent.join(name);
        std::fs::write(&path, "#!/bin/sh\nexit 0\n").unwrap();
        std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o755)).unwrap();
    }
    let context = DiscoveryContext::new(Platform::Linux, "bash", first.to_str(), None);
    for row in golden()["lookup"].as_array().unwrap() {
        // Executable discovery owns the public additional-path lookup API.
        let found = find_in_path(
            &context,
            row["command"].as_str().unwrap(),
            &[extra.to_str().unwrap().to_owned()],
        );
        let normalized = found.map(|p| p.replace(dir.to_str().unwrap(), "<ROOT>"));
        assert_eq!(
            serde_json::to_value(normalized).unwrap(),
            row["found"],
            "{row}"
        );
    }
}
